expression:
coalesce(
  modal_within(
    coalesce(
      recode_values(Sex, 0 ~ "Male", 1 ~ "Female"),
      recode_values(Gender, "Jongen" ~ "Male", "Meisje" ~ "Female", "Anders" ~ "Other")
    ),
    ID
  ),
  "Unknown"
)

local({
  grade <- carry_within(Grade, ID, order = match(wave, c("E1", "E2")))
  if_else(is.na(grade), NA_character_, paste("Grade", grade))
})
